/* ---- "what kind of change?" choices of a case type ---- */
const optPicker=(options,have)=>`<div class="op-list">${options.map(o=>{const h=have&&have.find(x=>x.name===o.name);return `<div class="op-item"><label class="op-main"><input type="checkbox" class="op-c" data-n="${esc(o.name)}"><span>${esc(o.name)}</span>${h?`<small class="text-muted ms-auto">on this case${h.actions&&h.actions.length?': '+esc(h.actions.join(', ')):''}</small>`:''}</label>${o.actions&&o.actions.length?`<div class="op-acts d-none">${o.actions.map(a=>`<label class="op-act"><input type="checkbox" class="op-a" data-n="${esc(a.name)}">${esc(a.name)}</label>`).join('')}</div>`:''}</div>`}).join('')}</div>`;
const optBind=root=>root.querySelectorAll('.op-c').forEach(c=>c.onchange=()=>{const a=c.closest('.op-item').querySelector('.op-acts');if(a)a.classList.toggle('d-none',!c.checked)});
